	if err != nil {
		return "", fmt.Errorf("listing resources: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading list response: %w", err)
	}

